function largestRectangleArea(heights){
  const n=heights.length;heights=[...heights,0];
  const stack=[];let maxArea=0;
  for(let i=0;i<=n;i++){
    while(stack.length&&heights[stack[stack.length-1]]>heights[i]){
      const h=heights[stack.pop()];
      const w=stack.length?i-stack[stack.length-1]-1:i;
      maxArea=Math.max(maxArea,h*w);
    }
    stack.push(i);
  }
  return maxArea;
}
function bruteForce(heights){let max=0;for(let i=0;i<heights.length;i++){let min=heights[i];for(let j=i;j<heights.length;j++){min=Math.min(min,heights[j]);max=Math.max(max,min*(j-i+1));}}return max;}
const largestRectangleAreaImpl=largestRectangleArea;
const bruteForceImpl=bruteForce;

