function maxCoins(nums){
  const a=[1,...nums,1];const n=a.length;
  const dp=Array.from({length:n},()=>new Array(n).fill(0));
  for(let len=2;len<n;len++)for(let i=0;i+len<n;i++){const j=i+len;for(let k=i+1;k<j;k++){dp[i][j]=Math.max(dp[i][j],a[i]*a[k]*a[j]+dp[i][k]+dp[k][j]);}}
  return dp[0][n-1];
}
function findMedianSortedArrays(nums1,nums2){
  if(nums1.length>nums2.length)return findMedianSortedArrays(nums2,nums1);
  const m=nums1.length,n=nums2.length;let lo=0,hi=m;
  while(lo<=hi){
    const i=(lo+hi)>>1;
    const j=Math.floor((m+n+1)/2)-i;
    const maxL1=i>0?nums1[i-1]:-Infinity;const minR1=i<m?nums1[i]:Infinity;
    const maxL2=j>0?nums2[j-1]:-Infinity;const minR2=j<n?nums2[j]:Infinity;
    if(maxL1<=minR2&&maxL2<=minR1){
      if((m+n)%2===1)return Math.max(maxL1,maxL2);
      return(Math.max(maxL1,maxL2)+Math.min(minR1,minR2))/2;
    }else if(maxL1>minR2)hi=i-1;
    else lo=i+1;
  }
}
function isMatch(s,p){
  const m=s.length,n=p.length;
  const dp=Array.from({length:m+1},()=>new Array(n+1).fill(false));
  dp[0][0]=true;
  for(let j=2;j<=n;j++)if(p[j-1]==='*')dp[0][j]=dp[0][j-2];
  for(let i=1;i<=m;i++)for(let j=1;j<=n;j++){
    if(p[j-1]==='*'){dp[i][j]=dp[i][j-2]||((p[j-2]==='.'||p[j-2]===s[i-1])&&dp[i-1][j]);}
    else{dp[i][j]=(p[j-1]==='.'||p[j-1]===s[i-1])&&dp[i-1][j-1];}
  }
  return dp[m][n];
}
const maxCoinsImpl=maxCoins;
const findMedianSortedArraysImpl=findMedianSortedArrays;
const isMatchImpl=isMatch;

