function calculateMinimumHP(dungeon){
  const m=dungeon.length,n=dungeon[0].length;
  const dp=Array.from({length:m+1},()=>new Array(n+1).fill(Infinity));
  dp[m][n-1]=dp[m-1][n]=1;
  for(let i=m-1;i>=0;i--)for(let j=n-1;j>=0;j--){const minNext=Math.min(dp[i+1][j],dp[i][j+1]);dp[i][j]=Math.max(1,minNext-dungeon[i][j]);}
  return dp[0][0];
}
function minRefuelStops(target,startFuel,stations){
  const heap=[];let fuel=startFuel,stops=0,i=0;
  while(fuel<target){
    while(i<stations.length&&stations[i][0]<=fuel){heap.push(stations[i][1]);heap.sort((a,b)=>b-a);i++;}
    if(!heap.length)return-1;
    fuel+=heap.shift();stops++;
  }
  return stops;
}
const calculateMinimumHPImpl=calculateMinimumHP;
const minRefuelStopsImpl=minRefuelStops;

