function identifyArchetypeImpl(description){
  const signals={
    'Interval DP with Reversal':['last','burst','range','cost to reduce'],
    'Reverse State DP':['health','survive','future constraint','bottom-right'],
    'Bitmask State':['visit all','n<=20','subset','tour'],
    'Monotonic Structure':['histogram','rectangle','span','extend until'],
    'Binary Search on Answer':['k-th','minimum x such that y','count pairs'],
  };
  for(const[arch,words]of Object.entries(signals)){
    if(words.some(w=>description.toLowerCase().includes(w)))return arch;
  }
  return'Unknown - needs deeper analysis';
}

function libraryStats(library){
  return{
    archetypeCount:library.length,
    totalProblems:library.reduce((s,a)=>s+a.problems.length,0)
  };
}

